Script:
# Validate paths before any installation files are removed. Reject links so lexical
# containment checks cannot be bypassed through a junction or symbolic link.
function Get-DeploymentDirectoryPath([string] $path) {
  if ([string]::IsNullOrWhiteSpace($path) -or -not [IO.Path]::IsPathRooted($path)) {
    throw "Deployment directory must be an absolute filesystem path: $path"
  }
  $full = [IO.Path]::GetFullPath($path)
  $root = [IO.Path]::GetPathRoot($full)
  if ([IO.Path]::DirectorySeparatorChar -eq '\' -and
      ([IO.Path]::GetPathRoot($path).Length -lt 3)) {
    throw "Deployment directory must be fully qualified: $path"
  }
  if ($full.TrimEnd('\', '/') -eq $root.TrimEnd('\', '/')) {
    throw "Deployment directory cannot be a filesystem root: $path"
  }
  $current = $full
  while ($current) {
    if (Test-Path -LiteralPath $current -ErrorAction Stop) {
      $entry = Get-Item -LiteralPath $current -Force -ErrorAction Stop
      if (-not $entry.PSIsContainer -or ($entry.Attributes -band [IO.FileAttributes]::ReparsePoint)) {
        throw "Deployment directory must not contain a file or linked directory in its path: $current"
      }
    }
    $current = [IO.Path]::GetDirectoryName($current)
  }
  return $full.TrimEnd('\', '/')
}

Import-Module PackageManagement -MinimumVersion 1.4 -ErrorAction Stop

Write-Host "Welcome to deploy package step template!"

$packagesRoot = $Jaws.PackageFolder
$workFolder = $pwd
$packageId = $Jaws.Parameters["STEP.PackageDetails.Package.PackageId"].Value
$packageVersion = $Jaws.Packages[$packageId].PackageVersion
$packageType = $Jaws.Packages[$packageId].PackageType
$packageFileName = $Jaws.Packages[$packageId].FileName
$packageDestination = $workFolder

# note: "$packageId.$packageVersion" is default NuGet Install-Package convention
$packageContents = Get-DeploymentDirectoryPath (Join-Path $packageDestination "$packageId.$packageVersion")

if (Test-Path -LiteralPath $packageContents -ErrorAction Stop) {
  if (-not (Test-Path -LiteralPath $packageContents -PathType Container -ErrorAction Stop) -or
      @(Get-ChildItem -LiteralPath $packageContents -Force -ErrorAction Stop).Count -ne 0) {
    throw "Extraction directory must be empty: $packageContents"
  }
} else {
  New-Item -Path $packageContents -ItemType Directory -ErrorAction Stop | Out-Null
}

Switch ($packageType) {
  "nupkg" {
    Write-Host "Unzipping package $packageId @ $packageVersion of type $packageType from $packagesRoot to $packageDestination using Install-Package cmdlet"
    $possibleNupkgToRemove = Join-Path $packageContents "$packageId.$packageVersion.nupkg"
    $existed = Test-Path $possibleNupkgToRemove
    # -ErrorAction Stop: Install-Package reports "No match was found..." as a *non-terminating* error.
    # Under the step's default error action (Continue) that would be swallowed and the script would carry on
    # to purge the installation directory with nothing to deploy. Force it to terminate so the step fails here.
    Install-Package -Name $packageId -RequiredVersion $packageVersion -Source $packagesRoot -Destination $packageDestination -ErrorAction Stop
    Write-Host "Package $packageId @ $packageVersion installed to $packageDestination"
    if (-not $existed -and (test-path $possibleNupkgToRemove)) {
      Write-Host "Removing $possibleNupkgToRemove after nupkg installation with Install-Package"
      Remove-Item -LiteralPath $possibleNupkgToRemove -ErrorAction Stop
    }
  }

  "zip" {
    $sourceZip = Join-Path $packagesRoot $packageFileName
    Write-Host "Unzipping package $packageId @ $packageVersion of type $packageType from $sourceZip to $packageContents using Expand-Archive cmdlet"
    Expand-Archive -LiteralPath $sourceZip -DestinationPath $packageContents -ErrorAction Stop
    Write-Host "Package $packageId @ $packageVersion unzipped to $packageContents"
  }

  "tar" {
    $sourceTar = Join-Path $packagesRoot $packageFileName
    Write-Host "Un-tar package $packageId @ $packageVersion of type $packageType from $sourceTar to $packageContents using tar.exe"
    tar xvf $sourceTar -C $packageContents
    if ($LASTEXITCODE -ne 0) { throw "Package extraction failed with exit code $LASTEXITCODE" }
    Write-Host "Package $packageId @ $packageVersion un-tarred to $packageContents"
  }

  "tar.gz" {
    $sourceTar = Join-Path $packagesRoot $packageFileName
    Write-Host "Unzip and un-tar package $packageId @ $packageVersion of type $packageType from $sourceTar to $packageContents using tar.exe"
    tar xvfz $sourceTar -C $packageContents
    if ($LASTEXITCODE -ne 0) { throw "Package extraction failed with exit code $LASTEXITCODE" }
    Write-Host "Package $packageId @ $packageVersion unzipped and un-tarred to $packageContents"
  }
  Default { throw "Unsupported package type: $packageType" }
}

Write-Host "Package files are ready for transformations at $packageContents"

# Safety guard: never proceed to purge/deploy if extraction produced nothing.
# This catches any case where the package could not be installed/unpacked (a failed or empty
# Install-Package, an empty archive, a file lock during parallel deployments, etc.) so we don't
# wipe the installation directory and leave the target with no files.
$deployableItems = @(Get-ChildItem -LiteralPath $packageContents -Force -ErrorAction Stop)
if ($deployableItems.Count -eq 0) {
  throw "Package $packageId @ $packageVersion produced no files in $packageContents. Aborting before touching the installation directory. This usually means the package could not be installed or unpacked (e.g. Install-Package found no matching package/version, the archive was empty, or the package file was locked by another process during a parallel deployment)."
}


#SCRIPTREFERENCE(STEP.CustomScripts.AfterPackageExtracted)


# config transform
$transforms = $Jaws.Parameters["STEP.Transformations.ConfigTransforms"].Value
if ([string]::IsNullOrWhiteSpace($transforms) -eq $false) {
  Write-Host "Executing config transformations"
  @($transforms -Split "`n").Trim() | ForEach-Object {
    $transform = $_
    if ([string]::IsNullOrWhiteSpace($transform) -eq $false) {
      Write-Host "Processing config transformation $transform"
      $idx = $transform.IndexOf(':')
      if ($idx -lt 0) {
        throw "Transformation $transform is invalid"
      }
      $type = $transform.Substring(0, $idx).Trim().ToLowerInvariant()
      $data = $transform.Substring($idx + 1).Split("=>")
      $fileIn = Join-Path $packageContents $data[0].Trim()
      $fileOut = Join-Path $packageContents $data[1].Trim()
      switch ($type) {
        "xml" {
          Convert-JawsXmlTransform -xml $fileOut -xdt $fileIn
        }
        "json" {
          Convert-JawsJsonTransform -json $fileOut -jsonTransform $fileIn
        }
        Default {
          throw "Transformation $type is not supported"
        }
      }
    }
  }
}
else {
  Write-Host "No config transformations defined"
}


#SCRIPTREFERENCE(STEP.CustomScripts.AfterConfigTransformed)


# variable replacement
$files = $Jaws.Parameters["STEP.Transformations.VariableReplacement"].Value
if ([string]::IsNullOrWhiteSpace($files) -eq $false) {
  Write-Host "Variable replacement - starting"
  @($files -Split "`n").Trim() | ForEach-Object {
    if ([string]::IsNullOrWhiteSpace($_) -eq $false) {
      Write-Host "Variable replacement - processing $_"
      $absoluteFilePath = Join-Path $packageContents $_
      Convert-JawsVariableReplace -sourcePath $absoluteFilePath -variables $Jaws.Parameters
      Write-Host "Variable replacement - done $_"
    }
  }
}
else {
  Write-Host "No files for variable replacement defined"
}

# hierarchical variable replacement
$files = $Jaws.Parameters["STEP.Transformations.JsonHierarchyVariableLocateAndReplace"].Value
if ([string]::IsNullOrWhiteSpace($files) -eq $false) {
  Write-Host "JSON hierarchical variable replacement - starting"
  @($files -Split "`n").Trim() | ForEach-Object {
    if ([string]::IsNullOrWhiteSpace($_) -eq $false) {
      Write-Host "JSON hierarchical variable replacement - processing $_"
      $absoluteFilePath = Join-Path $packageContents $_
      Convert-JawsJsonHierarchicalVariableReplace -sourcePath $absoluteFilePath -variables $Jaws.Parameters
      Write-Host "JSON hierarchical variable replacement - done $_"
    }
  }
}
else {
  Write-Host "No files for variable replacement defined"
}


#SCRIPTREFERENCE(STEP.CustomScripts.AfterVariablesReplaced)


function Assert-DeploymentTree([string] $path) {
  foreach ($entry in Get-ChildItem -LiteralPath $path -Force -ErrorAction Stop) {
    if ($entry.Attributes -band [IO.FileAttributes]::ReparsePoint) {
      throw "Deployment tree contains a symbolic link or junction: $($entry.FullName)"
    }
    if ($entry.PSIsContainer) { Assert-DeploymentTree $entry.FullName }
  }
}

# Explicit merging preserves unrelated files and overwrites matching files at any depth.
function Copy-DeploymentDirectory([string] $source, [string] $destination) {
  foreach ($entry in Get-ChildItem -LiteralPath $source -Force -ErrorAction Stop) {
    $target = Join-Path $destination $entry.Name
    if ($entry.PSIsContainer) {
      if (-not (Test-Path -LiteralPath $target -ErrorAction Stop)) {
        New-Item -Path $target -ItemType Directory -ErrorAction Stop | Out-Null
      } elseif (-not (Test-Path -LiteralPath $target -PathType Container -ErrorAction Stop)) {
        throw "Cannot copy directory over file: $target"
      }
      Copy-DeploymentDirectory $entry.FullName $target
    } else {
      if (Test-Path -LiteralPath $target -PathType Container -ErrorAction Stop) {
        throw "Cannot copy file over directory: $target"
      }
      Copy-Item -LiteralPath $entry.FullName -Destination $target -Force -ErrorAction Stop
    }
  }
}

$installDir = Get-DeploymentDirectoryPath $Jaws.Parameters["STEP.PackageDetails.InstallationDirectory"].Value
$packageContents = Get-DeploymentDirectoryPath $packageContents
$separator = [IO.Path]::DirectorySeparatorChar
$comparison = [StringComparison]::Ordinal
if ($separator -eq '\') { $comparison = [StringComparison]::OrdinalIgnoreCase }
if ($installDir.Equals($packageContents, $comparison) -or
    $installDir.StartsWith($packageContents + $separator, $comparison) -or
    $packageContents.StartsWith($installDir + $separator, $comparison)) {
  throw "Installation and extraction directories must not overlap: $installDir / $packageContents"
}

# Hooks and transformations may have changed the extracted contents; check again.
$deployableItems = @(Get-ChildItem -LiteralPath $packageContents -Force -ErrorAction Stop)
if ($deployableItems.Count -eq 0) { throw "Package contains no files to deploy: $packageContents" }
Assert-DeploymentTree $packageContents
$purge = $Jaws.Parameters["STEP.PackageDetails.PurgeInstallationDirectory"].Value -eq $true
if (Test-Path -LiteralPath $installDir -ErrorAction Stop) {
  Assert-DeploymentTree $installDir
  if ($purge) {
    Write-Host "Purging $installDir"
    Remove-JawsFolderContents -folder $installDir -ignoreErrors $false
    if (@(Get-ChildItem -LiteralPath $installDir -Force -ErrorAction Stop).Count -ne 0) {
      throw "Installation directory is not empty after cleanup: $installDir"
    }
    Write-Host "$installDir purged - ready to copy files"
  }
} else {
  New-Item -Path $installDir -ItemType Directory -ErrorAction Stop | Out-Null
}

Write-Host "Copying files from $packageContents to $installDir"
if ($purge) {
  foreach ($entry in $deployableItems) {
    Move-Item -LiteralPath $entry.FullName -Destination $installDir -Force -ErrorAction Stop
  }
} else {
  Copy-DeploymentDirectory $packageContents $installDir
}
Write-Host "All files copied"

#SCRIPTREFERENCE(STEP.CustomScripts.AfterPackageDeployed)
